"""Acceptance test agreed with the customer. Locked: do not edit this file."""

from todo import TodoList


def test_summary_line() -> None:
    todos = TodoList()
    todos.add("Write release notes")
    todos.add("Ship it")
    line = todos.summary()
    assert line == "2 tasks: Write release notes, Ship it"
    assert line.split(": ")[1] == "Write release notes, Ship it"
